#include "windows.h"
QWidget *settingsWindow(bool welcome){
    auto *w=new QMainWindow;w->setWindowTitle(welcome?"Bem-vindo ao Dell OS":"Configurações · Dell OS");w->resize(890,650);
    auto *scroll=new QScrollArea;scroll->setWidgetResizable(true);auto *page=new QWidget;auto *l=new QVBoxLayout(page);l->setContentsMargins(36,30,36,30);l->setSpacing(16);scroll->setWidget(page);w->setCentralWidget(scroll);
    auto *title=new QLabel(welcome?"Seu computador, um novo começo.":"Deixe do seu jeito.");title->setFont(QFont("Noto Sans",24,QFont::Bold));title->setWordWrap(true);l->addWidget(title);auto *sub=new QLabel("Dell OS 0.1 · Feito para aproveitar o que você já tem.");l->addWidget(sub);
    if(welcome){auto *note=new QLabel("No pendrive, você pode experimentar os aplicativos e testar Wi-Fi, som e câmera. As alterações da sessão Live não são preservadas ao desligar. Para usar todos os dias, escolha Instalar Dell OS.");note->setWordWrap(true);l->addWidget(note);}
    auto *appearance=new QGroupBox("Aparência");auto *form=new QFormLayout(appearance);auto *light=new QCheckBox("Tema claro");QSettings s("DellOS","desktop");light->setChecked(s.value("light",false).toBool());form->addRow(light);auto *wall=new QComboBox;wall->addItems({"aurora","oceano","areia"});wall->setCurrentText(s.value("wallpaper","aurora").toString());form->addRow("Wallpaper",wall);auto *preview=new QLabel;preview->setPixmap(Dell::wallpaper({540,170},wall->currentText()));form->addRow(preview);auto *apply=new QPushButton("Aplicar aparência");form->addRow(apply);l->addWidget(appearance);
    QObject::connect(wall,&QComboBox::currentTextChanged,w,[preview](const QString&t){preview->setPixmap(Dell::wallpaper({540,170},t));});QObject::connect(apply,&QPushButton::clicked,w,[light,wall]{QSettings s("DellOS","desktop");s.setValue("light",light->isChecked());s.setValue("wallpaper",wall->currentText());s.sync();Dell::theme();});
    auto *grid=new QGridLayout;l->addLayout(grid);int n=0;
    auto add=[grid,w,&n](const QString &name,const QString &description,const QString &command,const QStringList &args=QStringList{}){auto *b=new QPushButton(name+"\n"+description);b->setMinimumHeight(64);grid->addWidget(b,n/2,n%2);++n;QObject::connect(b,&QPushButton::clicked,w,[command,args]{Dell::external(command,args);});};
    add("Rede e Wi-Fi","Conexões, redes sem fio e Ethernet","nm-connection-editor");add("Som e microfone","Volume, dispositivos e entradas","pavucontrol");add("Tela","Resolução e monitores","lxrandr");add("Mouse e teclado","Velocidade, repetição e botões","lxinput");add("Energia","Bateria, suspensão e tampa","xfce4-power-manager-settings");add("Usuários","Contas e permissões","lxqt-admin-user");add("Data, hora e idioma","Preferências regionais e teclado","dell-regional");add("Atualizações","Consultar e instalar pacotes Debian","dell-updates");add("Ajuda e guia","Manual local, disponível sem internet","firefox-esr",{"file:///usr/share/dell-os/start/index.html"});
    if(QFile::exists("/run/live/medium/live/filesystem.squashfs"))add("Instalar Dell OS","Instalação guiada ou particionamento manual","install-dell-os");
    QFile mem("/proc/meminfo");QString memory;if(mem.open(QIODevice::ReadOnly))memory=QString::fromUtf8(mem.readAll()).section('\n',0,0);QFile cpu("/proc/cpuinfo");QString processor;if(cpu.open(QIODevice::ReadOnly)){for(const auto&line:QString::fromUtf8(cpu.readAll()).split('\n'))if(line.startsWith("model name")){processor=line.section(':',1).trimmed();break;}}
    auto *info=new QLabel("Sistema\n"+processor+"\n"+memory+"\nBase Debian 13 · Linux "+QSysInfo::kernelVersion()+" · "+QSysInfo::currentCpuArchitecture());info->setWordWrap(true);info->setTextInteractionFlags(Qt::TextSelectableByMouse);l->addWidget(info);l->addStretch();
    if(welcome){auto *done=new QPushButton("Começar a usar");l->addWidget(done);QObject::connect(done,&QPushButton::clicked,w,[w]{QSettings s("DellOS","desktop");s.setValue("welcomed",true);w->close();});}return w;
}
